+const form = document.querySelector("#terms-form");
+const termsCheckbox = document.querySelector("#terms");
+const termsError = document.querySelector("#terms-error");
+const formStatus = document.querySelector("#form-status");
+
+const updateTermsValidity = () => {
+  const isValid = termsCheckbox.checked;
+
+  termsCheckbox.setAttribute("aria-invalid", String(!isValid));
+  termsError.textContent = isValid ? "" : "Please agree to the terms of use to continue.";
+  return isValid;
+};
+
+termsCheckbox.addEventListener("change", () => {
+  updateTermsValidity();
+  formStatus.textContent = "";
+});
+
+form.addEventListener("submit", (event) => {
+  event.preventDefault();
+
+  if (!updateTermsValidity()) {
+    termsCheckbox.focus();
+    formStatus.textContent = "";
+    return;
+  }
+
+  formStatus.textContent = "Thanks. Your agreement has been submitted.";
+});
